 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the long L-shaped guide, made from one color: a straight vertical
    # run and a horizontal run meeting at an endpoint.
    candidates = []
    for color in {v for row in grid for v in row}:
        pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        for r, c in pts:
            for vd in (-1, 1):
                for hd in (-1, 1):
                    if (r + vd, c) not in pts or (r, c + hd) not in pts:
                        continue
                    vl = 1
                    x = r + vd
                    while (x, c) in pts:
                        vl += 1; x += vd
                    hl = 1
                    y = c + hd
                    while (r, y) in pts:
                        hl += 1; y += hd
                    if vl >= 4 and hl >= 4:
                        candidates.append((vl + hl, color, r, c, vd, hd))
    if not candidates:
        return [row[:] for row in grid]
    _, guide, er, ec, vd, hd = max(candidates)
    # Recolor the nearest non-guide object on the side opposite the
    # horizontal arm, provided it overlaps the guide's vertical span.
    seen = set(); choices = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == guide or (r, c) in seen:
                continue
            stack = [(r, c)]; seen.add((r, c)); comp = []
            while stack:
                x, y = stack.pop(); comp.append((x, y))
                for a, b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= a < h and 0 <= b < w and (a,b) not in seen and grid[a][b] == color:
                        seen.add((a,b)); stack.append((a,b))
            rows = [x for x,y in comp]; cols = [y for x,y in comp]
            # opposite the L's horizontal direction, across the vertical arm
            if (min(cols) < ec if hd > 0 else max(cols) > ec):
                overlap = sum(1 for x in rows if (x-er)*vd >= 0)
                if overlap:
                    dist = min(abs(y-ec) for x,y in comp)
                    choices.append((dist, -len(comp), color, comp))
    if not choices:
        return [row[:] for row in grid]
    _, _, _, target = min(choices)
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = guide
    return out
